#!/usr/bin/env bash
set -euo pipefail

mkdir -p src/resolveit/ticket src/test/resolveit/ticket

cat > src/resolveit/ticket/TicketReference.java <<'EOF'
package resolveit.ticket;

/** Builds a stable external reference code for a ticket. */
